// ===== src/codecs.js ===================================================
// @gcu/capsule — codec primitives (SPEC-capsule §6, §10, §6.4.1).
//
// Pure, browser-native, zero-dependency. The only non-native path is
// dictionary-keyed deflate (`deflate-dict.*`), which native CompressionStream
// does not yet expose; callers wanting it pass a pako-shaped `backend`
// (`{ inflateRaw, deflateRaw }`) — see deflateRaw/inflateRaw below. Without a
// backend the dictionary path throws EUNSUPPORTEDCODEC, which is the
// conforming way to decline the optional codec (§12, §17).

// ── byte helpers ───────────────────────────────────────────────────

/** Coerce ArrayBuffer / Buffer / number[] / Uint8Array → Uint8Array. */
function toU8(x) {
  if (x instanceof Uint8Array) return x;
  if (x instanceof ArrayBuffer) return new Uint8Array(x);
  if (ArrayBuffer.isView(x)) return new Uint8Array(x.buffer, x.byteOffset, x.byteLength);
  return Uint8Array.from(x);
}

// ── base64url (RFC 4648 §5, unpadded) ──────────────────────────────

function bytesToB64Url(bytes) {
  bytes = toU8(bytes);
  let s = '';
  for (let i = 0; i < bytes.length; i++) s += String.fromCharCode(bytes[i]);
  return btoa(s).replace(/\+/g, '-').replace(/\//g, '_').replace(/=+$/, '');
}

function b64UrlToBytes(s) {
  s = s.replace(/-/g, '+').replace(/_/g, '/');
  while (s.length % 4) s += '=';
  let bin;
  try { bin = atob(s); } catch { throw new Error('EDECODE'); }
  const out = new Uint8Array(bin.length);
  for (let i = 0; i < bin.length; i++) out[i] = bin.charCodeAt(i);
  return out;
}

// ── base45 (RFC 9285) ──────────────────────────────────────────────
// 45-char alphabet, 11 bits per pair of source bytes. 2 bytes → 3 chars;
// a trailing single byte → 2 chars. ~22% denser than base64url in QR
// alphanumeric mode (§6.4) at the cost of a longer character count.

const BASE45_ALPHABET = '0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ $%*+-./:';
const BASE45_LOOKUP = (() => {
  const m = new Map();
  for (let i = 0; i < BASE45_ALPHABET.length; i++) m.set(BASE45_ALPHABET[i], i);
  return m;
})();

function bytesToBase45(bytes) {
  bytes = toU8(bytes);
  let out = '';
  let i = 0;
  for (; i + 1 < bytes.length; i += 2) {
    let v = (bytes[i] << 8) | bytes[i + 1];   // 0..65535
    const c = v % 45; v = (v - c) / 45;
    const d = v % 45; v = (v - d) / 45;
    out += BASE45_ALPHABET[c] + BASE45_ALPHABET[d] + BASE45_ALPHABET[v]; // e = v, 0..32
  }
  if (i < bytes.length) {
    let v = bytes[i];                          // trailing single byte → 2 chars
    const c = v % 45; v = (v - c) / 45;
    out += BASE45_ALPHABET[c] + BASE45_ALPHABET[v];
  }
  return out;
}

function base45ToBytes(text) {
  const out = [];
  let i = 0;
  for (; i + 2 < text.length; i += 3) {
    const a = BASE45_LOOKUP.get(text[i]);
    const b = BASE45_LOOKUP.get(text[i + 1]);
    const c = BASE45_LOOKUP.get(text[i + 2]);
    if (a === undefined || b === undefined || c === undefined) throw new Error('EDECODE');
    const v = a + b * 45 + c * 45 * 45;
    if (v > 0xffff) throw new Error('EDECODE');
    out.push((v >> 8) & 0xff, v & 0xff);
  }
  if (i < text.length) {
    if (text.length - i !== 2) throw new Error('EDECODE');
    const a = BASE45_LOOKUP.get(text[i]);
    const b = BASE45_LOOKUP.get(text[i + 1]);
    if (a === undefined || b === undefined) throw new Error('EDECODE');
    const v = a + b * 45;
    if (v > 0xff) throw new Error('EDECODE');
    out.push(v);
  }
  return new Uint8Array(out);
}

// ── deflate-raw (RFC 1951, no zlib/gzip wrapper) ───────────────────
// Native CompressionStream("deflate-raw") for the plain path. The
// dictionary path delegates to an injected pako-shaped backend, since no
// shipping browser exposes a dictionary option on CompressionStream yet
// (§12). `backend` is `{ deflateRaw(bytes,{dictionary}), inflateRaw(...) }`
// — pako itself satisfies this, as does a thin node:zlib adapter for tests.

async function deflateRaw(bytes, opts = {}) {
  bytes = toU8(bytes);
  const { dictionary, backend } = opts;
  if (dictionary) {
    if (!backend) throw new Error('EUNSUPPORTEDCODEC');
    return toU8(await backend.deflateRaw(bytes, { dictionary: toU8(dictionary) }));
  }
  if (typeof CompressionStream !== 'undefined') {
    const stream = new Blob([bytes]).stream().pipeThrough(new CompressionStream('deflate-raw'));
    return new Uint8Array(await new Response(stream).arrayBuffer());
  }
  if (backend) return toU8(await backend.deflateRaw(bytes, {}));
  throw new Error('EUNSUPPORTEDCODEC');
}

async function inflateRaw(bytes, opts = {}) {
  bytes = toU8(bytes);
  const { dictionary, backend } = opts;
  if (dictionary) {
    if (!backend) throw new Error('EUNSUPPORTEDCODEC');
    try { return toU8(await backend.inflateRaw(bytes, { dictionary: toU8(dictionary) })); }
    catch (e) { throw e instanceof Error && /^E[A-Z]/.test(e.message) ? e : new Error('EDECODE'); }
  }
  if (typeof DecompressionStream !== 'undefined') {
    const stream = new Blob([bytes]).stream().pipeThrough(new DecompressionStream('deflate-raw'));
    try { return new Uint8Array(await new Response(stream).arrayBuffer()); }
    catch { throw new Error('EDECODE'); }
  }
  if (backend) return toU8(await backend.inflateRaw(bytes, {}));
  throw new Error('EUNSUPPORTEDCODEC');
}

// ── URL-fragment safety for base45 (`q:`) payloads (§6.4.1) ─────────
// The base45 alphabet contains exactly two fragment-illegal characters:
// space and `%`. Escape `%`→`%25` FIRST (so the `%` we introduce for the
// space isn't re-escaped), then space→`%20`. Decode with a SINGLE
// left-to-right pass recognizing only those two triplets — NOT sequential
// global replaces, and NOT decodeURIComponent (which throws on a lone `%`
// and over-decodes adversarial input). base64url payloads (`i:`/`inline:`)
// contain neither character, so this is a no-op for them — apply uniformly.

function fragmentEncode(capsule) {
  return capsule.replace(/%/g, '%25').replace(/ /g, '%20');
}

function fragmentDecode(s) {
  let out = '';
  for (let i = 0; i < s.length; ) {
    if (s[i] === '%' && s[i + 1] === '2' && s[i + 2] === '5') { out += '%'; i += 3; }
    else if (s[i] === '%' && s[i + 1] === '2' && s[i + 2] === '0') { out += ' '; i += 3; }
    else { out += s[i]; i++; }
  }
  return out;
}

// ── compact codec-character mapping (§6.3 / §6.4) ───────────────────

function compactCodecName(ch) {
  if (ch === 'r') return 'raw';
  if (ch === 'd') return 'deflate';
  if (ch === 'b') return 'brotli';   // optional; loaders reject if unimplemented
  throw new Error('EUNSUPPORTEDCODEC');
}

// ===== src/loaders/_fetch.js ===========================================
// @gcu/capsule — shared fetch helper for reference loaders (§8.2).
// Credentialless cross-origin GET; classified errors; forwards the abort
// signal. Reference loaders never opt into credentialed fetches (§22.3).

async function fetchBytes(url, ctx = {}, { headers } = {}) {
  let res;
  try {
    res = await fetch(url, {
      credentials: 'same-origin',           // anonymous for cross-origin (§22.3)
      redirect: 'follow',
      signal: ctx.signal,
      headers,
    });
  } catch (e) {
    if (e && e.name === 'AbortError') throw e;
    throw new Error('EFETCH');
  }
  if (!res.ok) throw new Error('EHTTP:' + res.status);
  const limit = ctx.options && ctx.options.maxBytes;
  const buf = await res.arrayBuffer();
  if (limit && buf.byteLength > limit) throw new Error('ETOOLARGE');
  return new Uint8Array(buf);
}

async function fetchJson(url, ctx = {}) {
  const bytes = await fetchBytes(url, ctx);
  try { return JSON.parse(new TextDecoder().decode(bytes)); }
  catch { throw new Error('EDECODE'); }
}

// ===== src/loaders/inline.js ===========================================
// @gcu/capsule — inline loaders (SPEC-capsule §6).
//
// Three schemes carry content directly in the capsule body, semantically
// equivalent modulo base alphabet (§6 / §17):
//
//   inline:<codec>:<base64url>      long form — readable, for docs/READMEs
//   i:<codec-char><base64url>       compact form — chat / short links
//   q:<codec-char>[.<dict>_]<base45> QR form — densest, only form with dict
//
// A loader takes (body, ctx) and returns Promise<Uint8Array>, where `body`
// is everything after the scheme's first `:` (what the dispatcher hands it).
// Because the three schemes frame their codec differently, each gets its own
// loader via makeInlineLoader(form). decodeInline() below is the standalone
// (dispatcher-free) entry point used by the public API.
//
// Dictionary material for `deflate-dict.*` comes from the resolution context:
//   ctx.options.inline = { dictionaries: { [id]: Uint8Array }, backend }
// `backend` is a pako-shaped { deflateRaw, inflateRaw } (see codecs.js).

// Parse the codec framing for each form into { codec, dictId, payload }.
// `codec` is normalized to: 'raw' | 'deflate' | 'deflate-dict' | 'brotli'.

function parseLong(body) {
  // body = "<codec>:<payload>", codec ∈ raw|deflate|brotli|deflate-dict.<id>
  const c = body.indexOf(':');
  if (c < 0) throw new Error('EDECODE');
  let codec = body.slice(0, c);
  const payload = body.slice(c + 1);
  let dictId = null;
  if (codec.startsWith('deflate-dict.')) {
    dictId = codec.slice('deflate-dict.'.length);
    if (!dictId) throw new Error('EDECODE');
    codec = 'deflate-dict';
  }
  return { codec, dictId, payload, base: 'b64' };
}

function parseCompactI(body) {
  // body = "<codec-char><payload>" — the i: form does NOT carry dictionaries (§6.3)
  if (!body) throw new Error('EDECODE');
  return { codec: compactCodecName(body[0]), dictId: null, payload: body.slice(1), base: 'b64' };
}

function parseCompactQ(body) {
  // body = "<codec-char>[.<dict-id>_]<payload>" — q: is the only compact form
  // with dictionary support (§6.4). The terminating `_` is unambiguous because
  // `_` is neither in the base45 alphabet nor a legal dict-id character (§12.1).
  if (!body) throw new Error('EDECODE');
  let codec = compactCodecName(body[0]);
  let rest = body.slice(1);
  let dictId = null;
  // Dict prefix is `.<dict-id>_` — but `.` is ALSO a base45 character, so a
  // plain payload can legitimately start with `.`. The disambiguator is `_`:
  // it is NOT in the base45 alphabet, so its presence unambiguously marks a
  // dict prefix. A leading `.` with no following `_` is just base45 data.
  if (rest[0] === '.' && rest.includes('_')) {
    const us = rest.indexOf('_');
    dictId = rest.slice(1, us);
    if (!dictId) throw new Error('EDECODE');
    rest = rest.slice(us + 1);
    if (codec !== 'deflate') throw new Error('EUNSUPPORTEDCODEC'); // dict is deflate-only for now
    codec = 'deflate-dict';
  }
  return { codec, dictId, payload: rest, base: 'b45' };
}

const PARSERS = { inline: parseLong, i: parseCompactI, q: parseCompactQ };

async function decodeParts(parts, ctx) {
  const { codec, dictId, payload, base } = parts;
  let bytes;
  try { bytes = base === 'b45' ? base45ToBytes(payload) : b64UrlToBytes(payload); }
  catch { throw new Error('EDECODE'); }

  if (codec === 'raw') return bytes;
  if (codec === 'brotli') throw new Error('EUNSUPPORTEDCODEC'); // optional, not implemented
  if (codec === 'deflate') return inflateRaw(bytes);
  if (codec === 'deflate-dict') {
    const cfg = (ctx && ctx.options && ctx.options.inline) || {};
    const dict = cfg.dictionaries && cfg.dictionaries[dictId];
    if (!dict) throw new Error('EUNSUPPORTEDCODEC'); // dict not registered → decline (§12)
    return inflateRaw(bytes, { dictionary: toU8(dict), backend: cfg.backend });
  }
  throw new Error('EUNSUPPORTEDCODEC');
}

/** Build a Loader bound to one inline scheme/form. */
function makeInlineLoader(form) {
  const parse = PARSERS[form];
  if (!parse) throw new Error('programmer error: unknown inline form ' + form);
  return async (body, ctx) => decodeParts(parse(body), ctx);
}

const inlineLoader = makeInlineLoader('inline'); // scheme: inline
const iLoader = makeInlineLoader('i');           // scheme: i
const qLoader = makeInlineLoader('q');           // scheme: q

/**
 * Standalone inline decode — parse the scheme ourselves and dispatch.
 * `opts` may carry { dictionaries, backend } directly (wrapped into the
 * ctx shape the loaders expect). Returns Uint8Array.
 */
async function decodeInline(capsule, opts = {}) {
  let p = capsule.startsWith('#') ? capsule.slice(1) : capsule;
  const c = p.indexOf(':');
  if (c < 0) throw new Error('ENOSCHEME');
  const scheme = p.slice(0, c);
  const body = p.slice(c + 1);
  if (!PARSERS[scheme]) throw new Error('EUNKNOWN');
  const ctx = { options: { inline: { dictionaries: opts.dictionaries, backend: opts.backend } } };
  return decodeParts(PARSERS[scheme](body), ctx);
}

// ===== src/loaders/url.js ==============================================
// @gcu/capsule — `url:` loader (SPEC-capsule §7.1).
// Body is a percent-encoded absolute HTTPS URL. HTTPS only; never follow an
// HTTPS→HTTP downgrade. The escape hatch for any CORS-open host not covered
// by a named scheme.

const urlLoader = async (body, ctx) => {
  let target;
  try { target = decodeURIComponent(body); } catch { throw new Error('EDECODE'); }
  let u;
  try { u = new URL(target); } catch { throw new Error('EDECODE'); }
  if (u.protocol !== 'https:') throw new Error('EFETCH'); // non-HTTPS rejected (§7.1)
  return fetchBytes(u.href, ctx);
};

// ===== src/loaders/gh.js ===============================================
// @gcu/capsule — `gh:` loader (SPEC-capsule §7.2).
//   gh:<owner>/<repo>[@<ref>]:<path>
// Fetches via jsDelivr by default (stable, cached) or raw.githubusercontent
// when ctx.options.gh.endpoint === 'raw'. ref defaults to HEAD.

const ghLoader = async (body, ctx = {}) => {
  // Split owner/repo[@ref] from path at the FIRST ':' — paths can't contain ':'
  // in this grammar, and refs/owners/repos can't either.
  const colon = body.indexOf(':');
  if (colon < 0) throw new Error('EDECODE');
  const locator = body.slice(0, colon);
  const path = body.slice(colon + 1);
  if (!path) throw new Error('EDECODE');

  let repoPart = locator, ref = 'HEAD';
  const at = locator.indexOf('@');
  if (at >= 0) { repoPart = locator.slice(0, at); ref = locator.slice(at + 1) || 'HEAD'; }

  const slash = repoPart.indexOf('/');
  if (slash < 0) throw new Error('EDECODE');
  const owner = repoPart.slice(0, slash);
  const repo = repoPart.slice(slash + 1);
  if (!owner || !repo) throw new Error('EDECODE');

  const endpoint = (ctx.options && ctx.options.gh && ctx.options.gh.endpoint) || 'jsdelivr';
  const url = endpoint === 'raw'
    ? `https://raw.githubusercontent.com/${owner}/${repo}/${ref}/${path}`
    : `https://cdn.jsdelivr.net/gh/${owner}/${repo}@${ref}/${path}`;
  return fetchBytes(url, ctx);
};

// ===== src/loaders/gist.js =============================================
// @gcu/capsule — `gist:` loader (SPEC-capsule §7.3).
//   gist:<id>[:<file>]
// Fetches the gist API, returns the named file, else the first file matching
// a shell-supplied default extension, else the first file. Falls back to the
// file's raw_url when the API reports it truncated.

const gistLoader = async (body, ctx = {}) => {
  const colon = body.indexOf(':');
  const id = colon < 0 ? body : body.slice(0, colon);
  const wanted = colon < 0 ? null : body.slice(colon + 1);
  if (!id) throw new Error('EDECODE');

  const meta = await fetchJson(`https://api.github.com/gists/${id}`, ctx);
  const files = meta && meta.files;
  if (!files || typeof files !== 'object') throw new Error('ENOTFOUND');
  const names = Object.keys(files);
  if (names.length === 0) throw new Error('ENOTFOUND');

  let pick = null;
  if (wanted) {
    pick = files[wanted];
    if (!pick) throw new Error('ENOTFOUND');
  } else {
    const defExt = ctx.options && ctx.options.gist && ctx.options.gist.defaultExt;
    if (defExt) pick = files[names.find(n => n.endsWith(defExt))];
    if (!pick) pick = files[names[0]];
  }

  if (pick.truncated && pick.raw_url) return fetchBytes(pick.raw_url, ctx);
  return new TextEncoder().encode(pick.content != null ? pick.content : '');
};

// ===== src/loaders/zenodo.js ===========================================
// @gcu/capsule — `zenodo:` loader (SPEC-capsule §7.4).
//   zenodo:<record-id>[:<file>]
// Fetches the record, then the named file's content endpoint. File selection
// when omitted mirrors gist (default-ext, then first file). Pinning is the
// caller's concern: use a version-specific record id (§7.4).

const zenodoLoader = async (body, ctx = {}) => {
  const colon = body.indexOf(':');
  const id = colon < 0 ? body : body.slice(0, colon);
  const wanted = colon < 0 ? null : body.slice(colon + 1);
  if (!id) throw new Error('EDECODE');

  const rec = await fetchJson(`https://zenodo.org/api/records/${id}`, ctx);
  const files = (rec && rec.files) || [];
  if (!Array.isArray(files) || files.length === 0) throw new Error('ENOTFOUND');

  const keyOf = f => f.key || f.filename || (f.links && f.links.self && f.links.self.split('/').pop());
  let pick = null;
  if (wanted) {
    pick = files.find(f => keyOf(f) === wanted);
    if (!pick) throw new Error('ENOTFOUND');
  } else {
    const defExt = ctx.options && ctx.options.zenodo && ctx.options.zenodo.defaultExt;
    if (defExt) pick = files.find(f => (keyOf(f) || '').endsWith(defExt));
    if (!pick) pick = files[0];
  }

  const key = keyOf(pick);
  const contentUrl = (pick.links && (pick.links.content || pick.links.download))
    || `https://zenodo.org/api/records/${id}/files/${encodeURIComponent(key)}/content`;
  return fetchBytes(contentUrl, ctx);
};

// ===== src/loaders/doi.js ==============================================
// @gcu/capsule — `doi:` loader (SPEC-capsule §7.5).
//   doi:<prefix>/<suffix>[#<file>]
// Resolves the DOI to its hosting system and delegates to a recognized
// downstream loader (currently Zenodo) via ctx.resolve. The `#file` suffix
// (inside the capsule body, not a second URL fragment) becomes the file
// selector for the downstream scheme. Unknown hosts → EUNSUPPORTEDDOI.

const doiLoader = async (body, ctx = {}) => {
  let name = body, file = null;
  const hash = body.indexOf('#');
  if (hash >= 0) { name = body.slice(0, hash); file = body.slice(hash + 1); }
  if (!name.includes('/')) throw new Error('EDECODE');

  let res;
  try {
    res = await fetch(`https://doi.org/${name}`, {
      method: 'GET', redirect: 'follow', credentials: 'same-origin', signal: ctx.signal,
    });
  } catch (e) {
    if (e && e.name === 'AbortError') throw e;
    throw new Error('EFETCH');
  }
  const dest = res.url || '';

  // Zenodo: .../record(s)/<id> — hand off to the zenodo scheme through the
  // dispatcher so its file-selection + content endpoint logic is reused.
  const z = dest.match(/zenodo\.org\/(?:record|records)\/(\d+)/);
  if (z) {
    if (typeof ctx.resolve !== 'function') throw new Error('EUNSUPPORTEDDOI');
    return ctx.resolve('zenodo:' + z[1] + (file ? ':' + file : ''));
  }
  throw new Error('EUNSUPPORTEDDOI'); // unrecognized host — caller may retry with url:
};

// ===== src/loaders/rentry.js ===========================================
// @gcu/capsule — `rentry:` loader (SPEC-capsule §7.6).
//   rentry:<paste-id>  →  https://rentry.co/<paste-id>/raw
// Rentry pastes are public; producers should label that at publication (§14).

const rentryLoader = async (body, ctx) => {
  if (!/^[A-Za-z0-9_-]+$/.test(body)) throw new Error('EDECODE');
  return fetchBytes(`https://rentry.co/${body}/raw`, ctx);
};

// ===== src/encode.js ===================================================
// @gcu/capsule — inline encoding (bytes/text → capsule). Split out so the
// share helpers (src/share.js) can reuse it without importing index.js.

const COMPACT_CHAR = { raw: 'r', deflate: 'd' };

/**
 * Encode content as an inline capsule.
 *
 * @param {Uint8Array|ArrayBuffer|string} content  string is UTF-8 encoded.
 * @param {object} [opts]
 *   form:    'i' (default) | 'q' | 'inline'   — compact / QR / long
 *   codec:   'deflate' (default) | 'raw'
 *   dictId:  dictionary id → uses deflate-dict.<id> (q: or inline: only)
 *   dictionary: Uint8Array dictionary bytes (required when dictId is set)
 *   backend: pako-shaped { deflateRaw, inflateRaw } for the dictionary path
 * @returns {Promise<string>} the capsule string (NOT fragment-escaped; wrap
 *   with fragmentEncode when placing in a URL fragment).
 */
async function encodeInline(content, opts = {}) {
  const form = opts.form || 'i';
  const codec = opts.codec || 'deflate';
  const bytes = typeof content === 'string' ? new TextEncoder().encode(content) : toU8(content);

  if (opts.dictId) {
    if (codec !== 'deflate') throw new Error('EUNSUPPORTEDCODEC');
    if (form === 'i') throw new Error('EUNSUPPORTEDCODEC'); // i: has no dict form (§6.3)
    const comp = await deflateRaw(bytes, { dictionary: opts.dictionary, backend: opts.backend });
    if (form === 'q') return `q:d.${opts.dictId}_` + bytesToBase45(comp);
    return `inline:deflate-dict.${opts.dictId}:` + bytesToB64Url(comp); // long form
  }

  const payloadBytes = codec === 'raw' ? bytes : await deflateRaw(bytes);
  if (form === 'q') return 'q:' + COMPACT_CHAR[codec] + bytesToBase45(payloadBytes);
  if (form === 'inline') return `inline:${codec}:` + bytesToB64Url(payloadBytes);
  return 'i:' + COMPACT_CHAR[codec] + bytesToB64Url(payloadBytes); // compact default
}

/** Decode an inline capsule to text (UTF-8). Convenience over decodeInline. */
async function decodeInlineText(capsule, opts) {
  return new TextDecoder().decode(await decodeInline(capsule, opts));
}

// ===== src/dispatcher.js ===============================================
// @gcu/capsule — dispatcher (SPEC-capsule §5, §9, §16).
//
// The glue between a capsule string and the loaders. createDispatcher()
// returns a registry pre-wired with all reserved schemes (§3.1); register()
// overwrites (so a shell can swap in a customized loader, e.g. an authed
// gh:), unregister() removes (subsequent resolve → EUNKNOWN). resolve()
// splits the capsule at the first ':', looks up the loader, and invokes it
// with a full ResolutionContext (including a `resolve` back-reference so
// loaders like doi: can delegate).

function createDispatcher(init = {}) {
  const loaders = new Map();
  const baseOptions = init.options || {};
  const baseOrigin = init.origin
    || (typeof location !== 'undefined' ? location.origin : undefined);

  function resolve(capsule, ctxOverride = {}) {
    let trimmed = capsule && capsule.startsWith('#') ? capsule.slice(1) : capsule;
    if (!trimmed) return Promise.reject(new Error('ENOSCHEME'));
    const idx = trimmed.indexOf(':');
    if (idx < 0) return Promise.reject(new Error('ENOSCHEME'));
    const scheme = trimmed.slice(0, idx);
    const body = trimmed.slice(idx + 1);
    const loader = loaders.get(scheme);
    if (!loader) return Promise.reject(new Error('EUNKNOWN'));
    const ctx = {
      origin: baseOrigin,
      options: baseOptions,
      signal: undefined,
      ...ctxOverride,
      resolve: (p, o) => resolve(p, o || ctxOverride),
    };
    // Loaders MUST surface operational failures as rejected promises (§8.2);
    // wrap so a synchronous throw still becomes a rejection.
    try { return Promise.resolve(loader(body, ctx)); }
    catch (e) { return Promise.reject(e); }
  }

  const dispatcher = {
    register(scheme, loader) { loaders.set(scheme, loader); },
    unregister(scheme) { loaders.delete(scheme); },
    has(scheme) { return loaders.has(scheme); },
    resolve,
  };

  // Default registrations (§3.1). A shell may unregister any of these to
  // shrink its attack surface (§11).
  dispatcher.register('inline', inlineLoader);
  dispatcher.register('i', iLoader);
  dispatcher.register('q', qLoader);
  dispatcher.register('url', urlLoader);
  dispatcher.register('gh', ghLoader);
  dispatcher.register('gist', gistLoader);
  dispatcher.register('zenodo', zenodoLoader);
  dispatcher.register('doi', doiLoader);
  dispatcher.register('rentry', rentryLoader);

  return dispatcher;
}

// ===== src/share.js ====================================================
// @gcu/capsule — share helpers (SPEC-capsule §14, §6.2).
//
// Size *literacy*, not size *limiting*. These helpers measure a capsule and
// report which channels its share URL fits in — they NEVER refuse to produce
// a capsule. The caller decides what to do with an over-budget result.
//
// CHANNELS is the single source of truth for the per-channel limits; the
// table in CAPSULES.md §6 mirrors these numbers (keep them in sync). Limits
// are practical "scans/pastes reliably" figures, not hard protocol maxima —
// verify against your real target if a few hundred bytes matter.

/**
 * Safe share-URL lengths per channel, in bytes (≈ characters for ASCII URLs).
 * `urlBytes` is the whole URL — origin + path + '#' + escaped capsule.
 */
const CHANNELS = [
  { id: 'sms',       label: 'SMS',                urlBytes: 160,   note: 'single GSM segment' },
  { id: 'qr-v10',    label: 'QR v10 (M ECC)',     urlBytes: 270,   note: 'gacha-sticker scale, ~1 inch' },
  { id: 'qr-v15',    label: 'QR v15 (M ECC)',     urlBytes: 500,   note: 'scans casually from a phone' },
  { id: 'qr-v20',    label: 'QR v20 (M ECC)',     urlBytes: 800,   note: 'larger but still reliable' },
  { id: 'email-safe',label: 'Email (safe)',       urlBytes: 2000,  note: 'some gateways reject longer' },
  { id: 'twitter',   label: 'Twitter/X, Slack',   urlBytes: 4000,  note: 'char limits; URL counts in full' },
  { id: 'telegram',  label: 'Telegram',           urlBytes: 4096,  note: 'per-message character cap' },
  { id: 'email',     label: 'Email (typical)',    urlBytes: 8000,  note: 'common practical ceiling' },
  { id: 'whatsapp',  label: 'WhatsApp/Signal',    urlBytes: 8000,  note: 'long links stay clickable, ~practical' },
  { id: 'addressbar',label: 'Address bar (Chrome/FF)', urlBytes: 32000, note: 'some servers truncate lower' },
];

/**
 * Report which channels a URL of `urlByteLength` bytes fits in.
 * @returns {Array<{id,label,urlBytes,note,ok:boolean}>}
 */
function channelFit(urlByteLength) {
  return CHANNELS.map(c => ({ ...c, ok: urlByteLength <= c.urlBytes }));
}

const byteLen = s => (typeof TextEncoder !== 'undefined'
  ? new TextEncoder().encode(s).length
  : Buffer.byteLength(s, 'utf8'));

/**
 * Measure an already-built capsule string.
 * @param {string} capsule
 * @param {object} [opts] baseUrl — origin+path the capsule rides on (e.g.
 *   'https://gentropic.org/cradle'); when given, urlBytes includes it + '#'
 *   and the §6.4.1 fragment escaping (which can lengthen q: payloads).
 * @returns {{capsule,capsuleBytes,fragment,urlBytes,fits,largestFit}}
 */
function measureCapsule(capsule, opts = {}) {
  const fragment = fragmentEncode(capsule);
  const base = opts.baseUrl ? byteLen(opts.baseUrl) + 1 : 0; // +1 for '#'
  const urlBytes = base + byteLen(fragment);
  const fits = channelFit(urlBytes);
  // CHANNELS is ascending by size, so the FIRST passing channel is the
  // tightest one it fits — and fitting the tightest means it fits everything
  // looser too. null when it fits nothing listed.
  const tightestFit = (fits.find(f => f.ok) || {}).id || null;
  return {
    capsule,
    capsuleBytes: byteLen(capsule),
    fragment,
    urlBytes,
    fits,
    tightestFit,
  };
}

/**
 * Encode content AND measure it in one call. Always returns the capsule —
 * `fits`/`suggestion` are advisory only (§14, revised: no gating).
 *
 * @param {Uint8Array|string} content
 * @param {object} [opts] form/codec/dictId/dictionary/backend (see encodeInline)
 *   + baseUrl (see measureCapsule). Defaults to form 'q' (QR-oriented) since
 *   the tightest channels are the ones that need measuring.
 * @returns {Promise<{capsule,capsuleBytes,fragment,urlBytes,fits,tightestFit,suggestion}>}
 */
async function makeShare(content, opts = {}) {
  const capsule = await encodeInline(content, { form: 'q', ...opts });
  const m = measureCapsule(capsule, opts);
  let suggestion = null;
  if (!m.tightestFit) {
    suggestion = 'Capsule exceeds every listed channel; consider a reference '
      + 'scheme (gh:/gist:/rentry:) so the URL carries a pointer, not the bytes.';
  } else if (m.tightestFit === 'addressbar') {
    suggestion = 'Fits only the address bar — too large for QR or messaging. '
      + 'Trim the payload or publish to a host and share a reference capsule.';
  }
  return { ...m, suggestion };
}

// ===== src/index.js ====================================================
// @gcu/capsule — public API (SPEC-capsule §13).
//
// A capsule is a compact string that resolves to bytes: carried inline
// (`inline:` / `i:` / `q:`, compressed into a URL fragment or QR) or
// referenced (`gh:` / `gist:` / `url:` / `zenodo:` / `doi:` / `rentry:`).
// This module re-exports the dispatcher, the standalone inline encode/decode,
// the codec primitives, and every loader for tree-shaking.

// Codec primitives (advanced / direct use).

// Loaders (named, for selective registration).

// ── convenience resolve over a lazily-created default dispatcher ────

let _default = null;
function defaultDispatcher() { return _default || (_default = createDispatcher()); }

/** Resolve any capsule to bytes using a default dispatcher (§5). */
function resolve(capsule, ctx) { return defaultDispatcher().resolve(capsule, ctx); }

